?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($job['book_title'])?> | <?=e(APP_NAME)?></title><link rel="stylesheet" href="assets/style.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="side-brand" href="dashboard.php"><div class="brand-mark">BP</div><div><strong>BOOKPRINTERS</strong><small>& SHREEPUBLICATIONS</small></div></a><div class="side-label">WORKSPACE</div><a class="nav-link" href="dashboard.php"><span>▦</span> Overview</a><?php if(is_admin()): ?><a class="nav-link active" href="jobs.php"><span>▤</span> Production jobs</a><a class="nav-link" href="employees.php"><span>♙</span> Employees & access</a><?php endif; ?><div class="sidebar-bottom"><div class="user-mini"><div class="avatar"><?=e(strtoupper(substr(current_user()['full_name'],0,1)))?></div><div><strong><?=e(current_user()['full_name'])?></strong><small><?=is_admin()?'Administrator':'Employee'?></small></div></div><a class="nav-link logout" href="logout.php"><span>↪</span> Sign out</a></div></aside><main class="main"><header class="topbar"><div><p class="eyebrow">PRODUCTION / JOB DETAILS</p><h1>Production details</h1></div><a class="btn secondary" href="<?=is_admin()?'jobs.php':'dashboard.php'?>">← Back</a></header><section class="job-detail-head"><div class="book-cover-large">▤</div><div class="job-detail-title"><span class="status <?=$job['priority']==='urgent'?'urgent':'normal'?>"><?=e(ucfirst($job['priority']))?> priority</span><h2><?=e($job['book_title'])?></h2><p class="muted"><?=e($job['job_code'])?> · <?=number_format((int)$job['total_quantity'])?> copies<?= $job['client_name']?' · '.e($job['client_name']):'' ?></p><p class="small muted">Created <?=e(date('d M Y, g:i A',strtotime($job['created_at'])))?> · Due <?=e($job['due_date']?:'not set')?></p><?php if($job['notes']): ?><p><?=e($job['notes'])?></p><?php endif; ?></div></section><section class="panel"><div class="panel-heading"><div><h2>Production journey</h2><p class="muted small">Follow the job from printing through final packing.</p></div></div><div class="timeline"><?php foreach($updates as $u): ?><div class="timeline-item"><div class="timeline-icon <?=$u['status']==='completed'?'done':($u['status']==='in_progress'?'active':'')?>"><?=$u['status']==='completed'?'✓':$all[$u['stage']]['step']?></div><div class="timeline-body"><div class="timeline-heading"><div><h3><?=e($all[$u['stage']]['label'])?></h3><p class="muted small">Assigned to: <?=e($all[$u['stage']]['employee'])?></p></div><span class="status <?=e($u['status'])?>"><?=e(stage_status_label($u['status']))?></span></div><div class="quantity-bar"><div><span>Quantity completed</span><strong><?=number_format((int)$u['completed_quantity'])?> / <?=number_format((int)$job['total_quantity'])?></strong></div><div class="progress-track"><span style="width:<?=min(100,(int)round((int)$u['completed_quantity']/max(1,(int)$job['total_quantity'])*100))?>%"></span></div></div><?php if($u['note']): ?><p class="note-text"><?=e($u['note'])?></p><?php endif; ?><p class="small muted"><?=e($u['updated_at']?date('d M Y, g:i A',strtotime($u['updated_at'])):'Not updated')?></p><?php if(is_admin()||current_user()['assigned_stage']===$u['stage']): ?><a class="btn small-btn secondary" href="update.php?job_id=<?=$id?>&stage=<?=e($u['stage'])?>">Update stage →</a><?php endif; ?></div></div><?php endforeach; ?></div></section><footer class="footer">© <?=date('Y')?> BookPrinters & ShreePublications <span>Production made visible.</span></footer></main></div></body></html>
